package com.adent.orders.api; import com.adent.orders.domain.LaboratoryOrder; import com.adent.orders.repository.LaboratoryOrderRepository; import com.adent.patient.repository.PatientRepository; import com.adent.shared.exception.NotFoundException; import com.adent.shared.security.CurrentUser; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/laboratory") @PreAuthorize("hasAnyRole('OWNER','DENTIST','LAB_TECHNICIAN')") public class LaboratoryController { private final CurrentUser current;private final LaboratoryOrderRepository repo;private final PatientRepository patients;public LaboratoryController(CurrentUser c,LaboratoryOrderRepository r,PatientRepository p){current=c;repo=r;patients=p;} @GetMapping public List<LaboratoryOrder> list(){return repo.findByTenantIdOrderByCreatedAtDesc(current.tenantId());}@GetMapping("/patient/{id}") public List<LaboratoryOrder> patient(@PathVariable UUID id){return repo.findByTenantIdAndPatientIdOrderByCreatedAtDesc(current.tenantId(),id);}@PostMapping @PreAuthorize("hasRole('DENTIST')") public LaboratoryOrder create(@RequestBody Request r){patients.findByIdAndTenantId(r.patientId(),current.tenantId()).orElseThrow(()->new NotFoundException("Paciente no encontrado"));LaboratoryOrder o=new LaboratoryOrder();o.setTenantId(current.tenantId());o.setPatientId(r.patientId());o.setEncounterId(r.encounterId());o.setRequestedByStaffId(r.requestedByStaffId());o.setToothCode(r.toothCode());o.setWorkType(r.workType());o.setInstructions(r.instructions());o.setDueDate(r.dueDate());return repo.save(o);}@PatchMapping("/{id}/status") @PreAuthorize("hasRole('LAB_TECHNICIAN')") public LaboratoryOrder status(@PathVariable UUID id,@RequestParam String status,@RequestParam(required=false) String notes){LaboratoryOrder o=repo.findByIdAndTenantId(id,current.tenantId()).orElseThrow(()->new NotFoundException("Orden no encontrada"));o.setStatus(status);o.setResultNotes(notes);if("DELIVERED".equals(status))o.setDeliveredAt(OffsetDateTime.now());return repo.save(o);} public record Request(UUID patientId,UUID encounterId,UUID requestedByStaffId,String toothCode,String workType,String instructions,LocalDate dueDate){} }
